// ChatMessage is the platform's own message type, declared as an
// external type instead of being copied into this file. One
// declaration, one shape, no drift between Flows.
var messages = new List<ChatMessage>
{
    // The system message sets the behaviour, the user message asks.
    // Keeping them as data — not as one glued string — is what makes
    // a prompt reviewable and testable.
    new ChatMessage() { Role = "system", Content = $"Answer in a {Input.tone} tone." },
    new ChatMessage() { Role = "user", Content = Input.question }
};

Logger.LogInformation($"prompt built from {messages.Count} messages");
return messages;

